def numsSameConsecDiff(n: int, k: int) -> list[int]:
    res = []
    def dfs(num, count):
        if count == n:
            res.append(num)
            return
        last = num % 10
        next_digits = {last + k, last - k}
        for d in next_digits:
            if 0 <= d <= 9:
                dfs(num * 10 + d, count + 1)
    for start in range(1, 10):
        dfs(start, 1)
    return sorted(res)

